        $this->interesadossScheduledForDeletion = $interesadossToDelete;

        foreach ($interesadossToDelete as $interesadosRemoved) {
            $interesadosRemoved->setTipoIdentificacion(null);
        }

        $this->collInteresadoss = null;
        foreach ($interesadoss as $interesados) {
            $this->addInteresados($interesados);
        }

        $this->collInteresadoss = $interesadoss;
        $this->collInteresadossPartial = false;

        return $this;
    }

    /**
     * Returns the number of related Interesados objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related Interesados objects.
     * @throws PropelException
     */
    public function countInteresadoss(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collInteresadossPartial && !$this->isNew();
        if (null === $this->collInteresadoss || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collInteresadoss) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getInteresadoss());
            }
            $query = InteresadosQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByTipoIdentificacion($this)
                ->count($con);
        }

        return count($this->collInteresadoss);
    }

    /**
     * Method called to associate a Interesados object to this object
     * through the Interesados foreign key attribute.
     *
     * @param    Interesados $l Interesados
     * @return TipoIdentificacion The current object (for fluent API support)
     */
    public function addInteresados(Interesados $l)
    {
        if ($this->collInteresadoss === null) {
            $this->initInteresadoss();
            $this->collInteresadossPartial = true;
        }

        if (!in_array($l, $this->collInteresadoss->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddInteresados($l);

            if ($this->interesadossScheduledForDeletion and $this->interesadossScheduledForDeletion->contains($l)) {
                $this->interesadossScheduledForDeletion->remove($this->interesadossScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	Interesados $interesados The interesados object to add.
     */
    protected function doAddInteresados($interesados)
    {
        $this->collInteresadoss[]= $interesados;
        $interesados->setTipoIdentificacion($this);
    }

    /**
     * @param	Interesados $interesados The interesados object to remove.
     * @return TipoIdentificacion The current object (for fluent API support)
     */
    public function removeInteresados($interesados)
    {
        if ($this->getInteresadoss()->contains($interesados)) {
            $this->collInteresadoss->remove($this->collInteresadoss->search($interesados));
            if (null === $this->interesadossScheduledForDeletion) {
                $this->interesadossScheduledForDeletion = clone $this->collInteresadoss;
                $this->interesadossScheduledForDeletion->clear();
            }
            $this->interesadossScheduledForDeletion[]= clone $interesados;
            $interesados->setTipoIdentificacion(null);
        }

        return $this;
    }


