    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collRepresentanteLegals) {
                foreach ($this->collRepresentanteLegals as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collDirectorioExternos) {
                foreach ($this->collDirectorioExternos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collDirectorioExternoHists) {
                foreach ($this->collDirectorioExternoHists as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collInteresadoss) {
                foreach ($this->collInteresadoss as $o) {
                    $o->clearAllReferences($deep);
                }
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collRepresentanteLegals instanceof PropelCollection) {
            $this->collRepresentanteLegals->clearIterator();
        }
        $this->collRepresentanteLegals = null;
        if ($this->collDirectorioExternos instanceof PropelCollection) {
            $this->collDirectorioExternos->clearIterator();
        }
        $this->collDirectorioExternos = null;
        if ($this->collDirectorioExternoHists instanceof PropelCollection) {
            $this->collDirectorioExternoHists->clearIterator();
        }
        $this->collDirectorioExternoHists = null;
        if ($this->collInteresadoss instanceof PropelCollection) {
            $this->collInteresadoss->clearIterator();
        }
        $this->collInteresadoss = null;
    }

